{
  "title": "夜宿云水客栈",
  "scene": "你来到江湖中著名的云水客栈，想在此过一晚。客栈的掌柜面带微笑，看上去十分和气。你注意到客栈的一角坐着一位身着黑衣、神情凝重的中年男子，不时向门外张望，似乎在等待什么人。另外，客栈门口的石碑上刻着一些关于门派恩怨的诗文，隐约透露出这里曾是某次江湖大战的交锋点。",
  "goal": "得到客栈的住宿",
  "clue": "掌柜的微笑与黑衣男子的紧张形成对比，石碑上的诗文暗示了客栈的历史。",
  "choices": [
    {
      "id": "A",
      "text": "直接向掌柜要房间",
      "outcome": "掌柜热情地为你准备了房间，还介绍了客栈的历史，让你对江湖有了更深的了解。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "与黑衣人交谈",
      "outcome": "黑衣人神色更加紧张，只说了句‘这里不是说话的地方’便匆匆离开，但掌柜看出了你的善意，允许你免费住一晚。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "研究石碑上的诗文",
      "outcome": "虽然诗文透露了客栈的过往，但掌柜似乎不太喜欢有人探究这些旧事，态度冷淡，不过最终还是给了你一个房间。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
